const found = await tools["glob"]({pattern:"packages/agents/src/core/**/*.ts", dir_path:root});
const paths = found.value?.files ?? found.value?.paths ?? [];
const rels = paths.map(p => p.startsWith(root + "/") ? p.slice(root.length + 1) : p);
