const root = "/Volumes/XS1000/acoliver/projects/llxprt/branch-5/llxprt-code";
const g = await tools["glob"]({pattern:"packages/agents/src/core/**/*.ts",dir_path:root,file_filtering_options:{respect_git_ignore:false,respect_llxprt_ignore:false}});
if (!g.ok) throw new Error(g.error.message);
const text = g.value.text;
const paths = [...text.matchAll(/^([^\n]+\.ts)$/gm)].map(m => m[1].trim()).filter(p => p.startsWith(root + "/"));
const result = {};
for (let i = 0; i < paths.length; i += 40) {
  const chunk = paths.slice(i, i + 40).map(p => p.slice(root.length + 1));
  const r = await tools["read_many_files"]({paths:chunk,useDefaultExcludes:false,file_filtering_options:{respect_git_ignore:false,respect_llxprt_ignore:false}});
  if (!r.ok) throw new Error(r.error.message);
  const content = r.value.text;
  for (const rel of chunk) {
    const marker = `--- ${rel} ---\n`;
    const absMarker = `--- ${root}/${rel} ---\n`;
    const start = content.indexOf(marker) >= 0 ? content.indexOf(marker) + marker.length : content.indexOf(absMarker) + absMarker.length;
    const next = content.indexOf("\n--- ", start);
    result[rel] = content.slice(start, next < 0 ? content.length : next).replace(/\n--- End of content ---\s*$/, "");
  }
}
return result;
